<?php
/**
 * Merge only fresh, owned PHPUnit artifacts and export relative numeric coverage.
 *
 * @package XNetVN\AgentHubWP
 */

declare(strict_types=1);

use SebastianBergmann\CodeCoverage\CodeCoverage;
use SebastianBergmann\CodeCoverage\Node\File;

if ( '1' !== getenv( 'XNETVN_RTL' ) ) {
	exit( 2 );
}
require dirname( __DIR__, 2 ) . '/vendor/autoload.php';
// phpcs:disable WordPress.WP.AlternativeFunctions -- Service-free reporting of private files generated by the isolated test runner.

/**
 * Keep each suite's coverage independent from the later combined result.
 *
 * @param CodeCoverage $coverage Verified artifact.
 * @return array<string,array<string,int|float|null>>
 */
function xnetvn_agent_hub_wp_coverage_suite_totals( CodeCoverage $coverage ): array {
	$totals    = array();
	$pure_auth = array( 'FailureReason', 'GeneratedKey', 'HeaderExtractor', 'IssuedKey', 'KeyGenerator', 'KeyHasher', 'ParsedToken', 'Pepper', 'StoredKey', 'TokenParser' );
	foreach ( $coverage->getReport() as $file ) {
		if ( ! $file instanceof File ) {
			continue;
		}
		$relative = substr( $file->pathAsString(), strlen( '/work/' ) );
		$group    = str_starts_with( $relative, 'src/' ) ? ( explode( '/', $relative )[1] ?? 'root' ) : 'EntryPoints';
		$names    = array( 'overall', $group );
		if ( 'Auth' === $group && in_array( basename( $relative, '.php' ), $pure_auth, true ) ) {
			$names[] = 'PureAuth';
		}
		foreach ( $names as $name ) {
			$totals[ $name ]              ??= array(
				'executable' => 0,
				'covered'    => 0,
			);
			$totals[ $name ]['executable'] += $file->numberOfExecutableLines();
			$totals[ $name ]['covered']    += $file->numberOfExecutedLines();
		}
	}
	foreach ( $totals as &$row ) {
		$row['percent'] = $row['executable'] > 0 ? 100 * $row['covered'] / $row['executable'] : null;
	}
	unset( $row );
	ksort( $totals );
	return $totals;
}

/**
 * Read only the fixed artifact set from an owned, private run directory.
 *
 * @throws RuntimeException For missing, unsafe or incomplete evidence.
 */
function xnetvn_agent_hub_wp_coverage_report(): void {
	$directory = getenv( 'XNETVN_COVERAGE_DIR' );
	if ( ! is_string( $directory ) || 1 !== preg_match( '/\A\/work\/\.local\/coverage-[A-Za-z0-9]{6}\z/', $directory ) || is_link( $directory ) || 0700 !== ( fileperms( $directory ) & 0777 ) || fileowner( $directory ) !== posix_geteuid() ) {
		throw new RuntimeException( 'Coverage directory is unavailable or untrusted.' );
	}
	$merged           = null;
	$suites           = array();
	$expected_sources = array( '/work/xnetvn-agent-hub-wp.php', '/work/uninstall.php' );
	foreach ( new RecursiveIteratorIterator( new RecursiveDirectoryIterator( '/work/src', FilesystemIterator::SKIP_DOTS ) ) as $source ) {
		if ( $source->isFile() && 'php' === $source->getExtension() ) {
			$expected_sources[] = $source->getRealPath();
		}
	}
	sort( $expected_sources, SORT_STRING );
	foreach ( array( 'unit', 'single-6.9', 'single-7.1.2', 'multisite-6.9', 'multisite-7.1.2' ) as $name ) {
		$path = $directory . '/' . $name . '.php';
		if ( ! is_file( $path ) || is_link( $path ) || fileowner( $path ) !== posix_geteuid() || 0 !== ( fileperms( $path ) & 0077 ) ) {
			throw new RuntimeException( 'Coverage artifact is unavailable or untrusted.' );
		}
		// PHPUnit's installed exporter produces executable serialization. Only this runner's
		// private fixed-name files are allowed; no caller-supplied code or external report is read.
		$coverage = require $path;
		if ( ! $coverage instanceof CodeCoverage ) {
			throw new RuntimeException( 'Coverage artifact type is invalid.' );
		}
		$observed_sources = $coverage->filter()->files();
		sort( $observed_sources, SORT_STRING );
		if ( $expected_sources !== $observed_sources ) {
			throw new RuntimeException( 'Coverage artifact excludes required source files.' );
		}
		$suites[ $name ] = xnetvn_agent_hub_wp_coverage_suite_totals( $coverage );
		if ( null === $merged ) {
			$merged = $coverage;
		} else {
			$merged->merge( $coverage );
		}
	}
	$files  = array();
	$groups = array();
	$data   = $merged->getData()->lineCoverage();
	foreach ( $merged->getReport() as $file ) {
		if ( ! $file instanceof File ) {
			continue;
		}
		$absolute = $file->pathAsString();
		if ( ! in_array( $absolute, $expected_sources, true ) ) {
			throw new RuntimeException( 'Coverage source boundary is invalid.' );
		}
		$relative = substr( $absolute, strlen( '/work/' ) );
		$total    = $file->numberOfExecutableLines();
		$covered  = $file->numberOfExecutedLines();
		$missing  = array();
		foreach ( $data[ $absolute ] ?? array() as $line => $tests ) {
			if ( array() === $tests ) {
				$missing[] = $line;
			}
		}
		$files[ $relative ]              = array(
			'executable'      => $total,
			'covered'         => $covered,
			'percent'         => $total > 0 ? 100 * $covered / $total : null,
			'uncovered_lines' => $missing,
		);
		$group                           = str_starts_with( $relative, 'src/' ) ? ( explode( '/', $relative )[1] ?? 'root' ) : 'EntryPoints';
		$groups[ $group ]              ??= array(
			'executable' => 0,
			'covered'    => 0,
		);
		$groups[ $group ]['executable'] += $total;
		$groups[ $group ]['covered']    += $covered;
	}
	foreach ( $groups as &$group ) {
		$group['percent'] = $group['executable'] > 0 ? 100 * $group['covered'] / $group['executable'] : null;
	}
	unset( $group );
	$total   = $merged->getReport()->numberOfExecutableLines();
	$covered = $merged->getReport()->numberOfExecutedLines();
	if ( $total < 1 || ! $files ) {
		throw new RuntimeException( 'Coverage evidence is empty.' );
	}
	ksort( $files );
	ksort( $groups );
	echo json_encode(
		array(
			'format'  => 1,
			'driver'  => 'Xdebug3.5.3 / php-code-coverage9.2 / PHPUnit9.6',
			'scope'   => 'All src PHP files plus bootstrap/uninstall entrypoints; unit plus two single-site and two multisite integration suites. Does not include browser/HTTP coverage or prove branch/path coverage.',
			'overall' => array(
				'executable' => $total,
				'covered'    => $covered,
				'percent'    => 100 * $covered / $total,
			),
			'groups'  => $groups,
			'suites'  => $suites,
			'files'   => $files,
		),
		JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR
	) . "\n";
}

xnetvn_agent_hub_wp_coverage_report();
